//! In-memory state: onboarded issuers, issued credentials and status lists.

use std::collections::HashMap;
use std::sync::Mutex;

use affinidi_did_common::Document;
use serde::{Deserialize, Serialize};

use crate::status::{StatusList, DEFAULT_CAPACITY};

const ONBOARDING_DATA: &str = include_str!("../data/onboarded-issuers.json");

/// An issuer approved to issue through the service.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct OnboardedIssuer {
    pub did: String,
    pub name: String,
    pub onboarded_at: String,
    pub document: Document,
}

/// What the service remembers about a credential it issued.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CredentialRecord {
    pub id: String,
    pub issuer: String,
    pub subject: String,
    pub status_list: String,
    pub status_index: usize,
    pub expires_at: i64,
}

#[derive(Default)]
struct Inner {
    issuers: HashMap<String, OnboardedIssuer>,
    credentials: HashMap<String, CredentialRecord>,
    status_lists: HashMap<String, StatusList>,
}

#[derive(Default)]
pub struct Store {
    inner: Mutex<Inner>,
}

impl Store {
    pub fn new() -> Self {
        Store::default()
    }

    /// A store holding every issuer in `data/onboarded-issuers.json`.
    pub fn from_onboarding_data() -> Result<Self, serde_json::Error> {
        let issuers: Vec<OnboardedIssuer> = serde_json::from_str(ONBOARDING_DATA)?;
        let store = Store::new();
        for issuer in issuers {
            store.record_onboarded_issuer(issuer);
        }
        Ok(store)
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
        self.inner.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn record_onboarded_issuer(&self, issuer: OnboardedIssuer) {
        self.lock().issuers.insert(issuer.did.clone(), issuer);
    }

    pub fn onboarded_issuer(&self, did: &str) -> Option<OnboardedIssuer> {
        self.lock().issuers.get(did).cloned()
    }

    pub fn onboarded_issuers(&self) -> Vec<OnboardedIssuer> {
        let mut issuers: Vec<_> = self.lock().issuers.values().cloned().collect();
        issuers.sort_by(|a, b| a.did.cmp(&b.did));
        issuers
    }

    pub fn record_credential(&self, record: CredentialRecord) {
        self.lock().credentials.insert(record.id.clone(), record);
    }

    pub fn credential(&self, id: &str) -> Option<CredentialRecord> {
        self.lock().credentials.get(id).cloned()
    }

    /// Reserves an index in `list`, creating the list on first use.
    pub fn allocate_status_index(&self, list: &str) -> Option<usize> {
        self.lock()
            .status_lists
            .entry(list.to_string())
            .or_insert_with(|| StatusList::new(DEFAULT_CAPACITY))
            .allocate()
    }

    /// Sets the bit at `index` in `list`; `false` if there is no such list.
    pub fn set_status(&self, list: &str, index: usize, revoked: bool) -> bool {
        match self.lock().status_lists.get_mut(list) {
            Some(status) => {
                status.set(index, revoked);
                true
            }
            None => false,
        }
    }

    pub fn is_revoked(&self, list: &str, index: usize) -> Option<bool> {
        self.lock().status_lists.get(list).map(|status| status.is_set(index))
    }

    /// The published form of `list`.
    pub fn encoded_status_list(&self, list: &str) -> Option<String> {
        self.lock().status_lists.get(list).map(StatusList::encode)
    }
}
//! Onboarding issuers and issuing credentials on their behalf.

use ed25519_dalek::{SigningKey, VerifyingKey};
use serde_json::{json, Value};
use thiserror::Error;

use crate::credential::{self, Disclosure, CREDENTIALS_CONTEXT};
use crate::resolver::{ResolveError, Resolver};
use crate::store::{CredentialRecord, OnboardedIssuer, Store};

#[derive(Debug, Error)]
pub enum OnboardError {
    #[error(transparent)]
    Resolve(#[from] ResolveError),
    #[error("{0} publishes no assertion key")]
    NoAssertionKey(String),
}

/// Approves an issuer: resolves its DID and records it with its document.
pub fn onboard(
    resolver: &Resolver,
    store: &Store,
    did: &str,
    name: &str,
    onboarded_at: &str,
) -> Result<OnboardedIssuer, OnboardError> {
    let document = resolver.resolve(did)?;
    if document.assertion_method.is_empty() {
        return Err(OnboardError::NoAssertionKey(did.to_string()));
    }
    let record = OnboardedIssuer {
        did: did.to_string(),
        name: name.to_string(),
        onboarded_at: onboarded_at.to_string(),
        document,
    };
    store.record_onboarded_issuer(record.clone());
    Ok(record)
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum IssueError {
    #[error("holder {0} is not a did:key")]
    InvalidHolder(String),
    #[error("credential would expire before it becomes valid")]
    InvalidValidity,
    #[error("status list {0} is full")]
    StatusListFull(String),
}

/// What a member asked for.
#[derive(Debug, Clone)]
pub struct CredentialRequest {
    /// The holder's `did:key`.
    pub holder: String,
    /// Added to `type` after `VerifiableCredential`.
    pub credential_type: String,
    pub claims: Vec<(String, Value)>,
    /// Unix seconds.
    pub issued_at: i64,
    /// Unix seconds; defaults to `issued_at`.
    pub not_before: Option<i64>,
    /// Unix seconds.
    pub expires_at: i64,
}

/// A signed credential plus the disclosures only its holder receives.
#[derive(Debug, Clone)]
pub struct IssuedCredential {
    pub credential: Value,
    pub disclosures: Vec<Disclosure>,
}

/// An onboarded issuer's signing identity.
pub struct Issuer {
    did: String,
    verification_method: String,
    key: SigningKey,
}

impl Issuer {
    /// `verification_method` is the DID URL of the key in the issuer's document.
    pub fn new(did: &str, verification_method: &str, seed: &[u8; 32]) -> Self {
        Issuer {
            did: did.to_string(),
            verification_method: verification_method.to_string(),
            key: SigningKey::from_bytes(seed),
        }
    }

    pub fn did(&self) -> &str {
        &self.did
    }

    pub fn verifying_key(&self) -> VerifyingKey {
        self.key.verifying_key()
    }

    /// The status list this issuer's credentials are indexed into.
    pub fn status_list(&self) -> String {
        format!("{}#revocation", self.did)
    }

    pub fn issue(&self, store: &Store, request: &CredentialRequest) -> Result<IssuedCredential, IssueError> {
        let holder_key = request.holder.strip_prefix("did:key:").unwrap_or_default();
        match affinidi_encoding::decode_multikey_with_codec(holder_key) {
            Ok((affinidi_encoding::ED25519_PUB, _)) => {}
            _ => return Err(IssueError::InvalidHolder(request.holder.clone())),
        }
        let not_before = request.not_before.unwrap_or(request.issued_at);
        if request.expires_at < not_before {
            return Err(IssueError::InvalidValidity);
        }

        let disclosures: Vec<Disclosure> =
            request.claims.iter().map(|(name, value)| Disclosure::new(name, value.clone())).collect();
        let mut digests: Vec<String> = disclosures.iter().map(Disclosure::digest).collect();
        digests.sort();

        let status_list = self.status_list();
        let status_index =
            store.allocate_status_index(&status_list).ok_or_else(|| IssueError::StatusListFull(status_list.clone()))?;

        let id = credential::random_urn();
        let mut vc = json!({
            "@context": [CREDENTIALS_CONTEXT],
            "id": id,
            "type": ["VerifiableCredential", request.credential_type],
            "issuer": self.did,
            "issued_at": request.issued_at,
            "not_before": not_before,
            "expires_at": request.expires_at,
            "credentialSubject": { "id": request.holder, "_sd": digests },
            "credentialStatus": {
                "type": "StatusListEntry",
                "statusListId": status_list,
                "statusListIndex": status_index,
            },
        });
        credential::sign(&mut vc, &self.key, &self.verification_method, "assertionMethod", request.issued_at);

        store.record_credential(CredentialRecord {
            id,
            issuer: self.did.clone(),
            subject: request.holder.clone(),
            status_list,
            status_index,
            expires_at: request.expires_at,
        });
        Ok(IssuedCredential { credential: vc, disclosures })
    }
}
//! Issuer and verifier service for membership credentials.
//!
//! - [`issuer`] onboards issuers and signs credentials for their members.
//! - [`verifier`] checks the presentations members show at the door.
//! - [`resolver`] turns a DID into its DID document; [`transport`] fetches
//!   the documents that are hosted rather than encoded in the DID.
//! - [`status`] and [`store`] keep issued credentials and their revocation state.
//! - [`notifier`] tells subscribed relying parties when a status changes;
//!   [`settings`] holds the tenants' subscriptions and [`webhook`] sends the
//!   calls.
//! - [`credential`] is the wire format shared by all of the above.

pub mod credential;
pub mod issuer;
pub mod notifier;
pub mod resolver;
pub mod settings;
pub mod status;
pub mod store;
pub mod transport;
pub mod verifier;
pub mod webhook;
//! Shared fixtures for the backend suite.
//!
//! Harbour Club is the issuer these tests sign with; `HARBOUR_*` are its key
//! and its published DID document. Holders are generated per test from a
//! fixed seed byte.
#![allow(dead_code)]

use std::sync::Arc;

use credentials_backend::credential::{self, Disclosure};
use credentials_backend::issuer::{CredentialRequest, IssuedCredential, Issuer};
use credentials_backend::resolver::{did_key_for, Resolver};
use credentials_backend::store::Store;
use credentials_backend::transport::StaticTransport;
use credentials_backend::verifier::{Submission, Verifier};
use ed25519_dalek::SigningKey;
use serde_json::{json, Value};

pub const HARBOUR_DID: &str = "did:web:members.harbourclub.example";
pub const HARBOUR_KEY_ID: &str = "did:web:members.harbourclub.example#key-1";
pub const HARBOUR_SEED: &str = "9f3688f6e8b93b0cfa3b11c28fbc25fe5440192ed82835e7fe3ab590f03f6c75";
pub const HARBOUR_PUBLIC: &str = "z6MkjgN85pffmWg8nS4P2epjg78ADoAaBs7jfzryUFx8vt6N";

/// 2026-06-01T00:00:00Z — "now" for every verifier in the suite.
pub const NOW: i64 = 1_780_272_000;
pub const DAY: i64 = 86_400;

pub const NONCE: &str = "n-0S6_WzA2Mj";
pub const DOMAIN: &str = "door.harbourclub.example";

pub fn seed(hex: &str) -> [u8; 32] {
    let mut out = [0u8; 32];
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap();
    }
    out
}

pub fn harbour() -> Issuer {
    Issuer::new(HARBOUR_DID, HARBOUR_KEY_ID, &seed(HARBOUR_SEED))
}

pub struct Holder {
    pub key: SigningKey,
    pub did: String,
}

impl Holder {
    pub fn new(seed_byte: u8) -> Self {
        let key = SigningKey::from_bytes(&[seed_byte; 32]);
        let did = did_key_for(&key.verifying_key());
        Holder { key, did }
    }

    pub fn key_id(&self) -> String {
        let fragment = self.did.trim_start_matches("did:key:");
        format!("{}#{}", self.did, fragment)
    }

    /// Builds and signs a presentation of `issued`, disclosing the claims named in `reveal`.
    pub fn present(&self, issued: &IssuedCredential, reveal: &[&str], nonce: &str, domain: &str) -> Value {
        let disclosures: Vec<&Disclosure> =
            issued.disclosures.iter().filter(|d| reveal.contains(&d.name.as_str())).collect();
        let mut vp = json!({
            "@context": ["https://www.w3.org/2018/credentials/v1"],
            "type": ["VerifiablePresentation"],
            "holder": self.did,
            "verifiableCredential": issued.credential,
            "disclosures": disclosures,
            "nonce": nonce,
            "domain": domain,
        });
        credential::sign(&mut vp, &self.key, &self.key_id(), "authentication", NOW);
        vp
    }
}

pub fn membership_request(holder: &Holder) -> CredentialRequest {
    CredentialRequest {
        holder: holder.did.clone(),
        credential_type: "MembershipCredential".into(),
        claims: vec![
            ("member".into(), json!(true)),
            ("tier".into(), json!("gold")),
            ("birthdate".into(), json!("1990-04-12")),
        ],
        issued_at: NOW - 30 * DAY,
        not_before: None,
        expires_at: NOW + 180 * DAY,
    }
}

pub fn store() -> Arc<Store> {
    Arc::new(Store::from_onboarding_data().expect("onboarding data parses"))
}

pub fn harbour_document() -> Value {
    json!({
        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
        "id": HARBOUR_DID,
        "verificationMethod": [{
            "id": HARBOUR_KEY_ID,
            "type": "Multikey",
            "controller": HARBOUR_DID,
            "publicKeyMultibase": HARBOUR_PUBLIC
        }],
        "authentication": [HARBOUR_KEY_ID],
        "assertionMethod": [HARBOUR_KEY_ID],
        "service": [{
            "id": format!("{HARBOUR_DID}#site"),
            "type": "LinkedDomains",
            "serviceEndpoint": "https://harbourclub.example/"
        }]
    })
}

pub const HARBOUR_URL: &str = "https://members.harbourclub.example/.well-known/did.json";

pub fn transport() -> StaticTransport {
    StaticTransport::default().with(HARBOUR_URL, harbour_document().to_string())
}

pub fn verifier(store: Arc<Store>) -> Verifier {
    let resolver = Resolver::new(Arc::new(transport()));
    Verifier::new(resolver, store).with_clock(|| NOW)
}

pub fn submission(request_id: &str, presentation: Value) -> Submission {
    Submission { request_id: request_id.into(), presentation }
}
mod common;

use credentials_backend::credential;
use credentials_backend::status::revoke_credential;
use credentials_backend::verifier::VerifyError;
use serde_json::json;

use common::*;

#[test]
fn a_presentation_discloses_only_the_requested_claims() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);

    let verified = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap();
    assert_eq!(verified.holder, holder.did);
    assert_eq!(verified.credential.issuer, HARBOUR_DID);
    assert_eq!(verified.claims.len(), 1);
    assert_eq!(verified.claims["member"], json!(true));
}

#[test]
fn every_claim_can_be_disclosed() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member", "tier", "birthdate"], NONCE, DOMAIN);

    let verified = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap();
    assert_eq!(verified.claims["tier"], json!("gold"));
    assert_eq!(verified.claims["birthdate"], json!("1990-04-12"));
}

#[test]
fn a_credential_verifies_on_its_own() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();

    let verified = verifier(store).verify_credential(&issued.credential).unwrap();
    assert_eq!(verified.issuer, HARBOUR_DID);
    assert_eq!(verified.subject, holder.did);
    assert_eq!(verified.expires_at, NOW + 180 * DAY);
    assert_eq!(verified.issuer_site.as_deref(), Some("https://harbourclub.example/"));
}

#[test]
fn the_issuer_document_is_the_one_harbour_publishes() {
    let doc = verifier(store()).resolve_issuer(HARBOUR_DID).unwrap();
    let key = doc.verification_method.iter().find(|vm| vm.id.as_str() == HARBOUR_KEY_ID).unwrap();
    assert_eq!(key.property_set["publicKeyMultibase"], HARBOUR_PUBLIC);
}

#[test]
fn a_presentation_for_another_nonce_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], "an-older-nonce", DOMAIN);
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::NonceMismatch), "{err:?}");
}

#[test]
fn a_presentation_for_another_domain_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, "door.elsewhere.example");
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::DomainMismatch), "{err:?}");
}

#[test]
fn the_same_submission_is_accepted_once() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let verifier = verifier(store);
    verifier.verify_presentation(&submission("req-1", vp.clone()), NONCE, DOMAIN).unwrap();
    let err = verifier.verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::Replay), "{err:?}");
}

#[test]
fn a_tampered_disclosure_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let tier = issued.disclosures.iter_mut().find(|d| d.name == "tier").unwrap();
    tier.value = json!("platinum");
    let vp = holder.present(&issued, &["tier"], NONCE, DOMAIN);
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::UndisclosedClaim(ref name) if name == "tier"), "{err:?}");
}

#[test]
fn a_tampered_credential_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    issued.credential["expires_at"] = json!(NOW + 3650 * DAY);
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::BadSignature(_)), "{err:?}");
}

#[test]
fn a_presentation_signed_by_someone_else_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let thief = Holder::new(9);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let mut vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    credential::sign(&mut vp, &thief.key, &holder.key_id(), "authentication", NOW);
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::BadSignature(_)), "{err:?}");
}

#[test]
fn a_credential_presented_by_another_holder_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let thief = Holder::new(9);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = thief.present(&issued, &["member"], NONCE, DOMAIN);
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::HolderMismatch), "{err:?}");
}

#[test]
fn an_expired_credential_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let mut request = membership_request(&holder);
    request.expires_at = NOW - DAY;
    let issued = harbour().issue(&store, &request).unwrap();
    let err = verifier(store).verify_credential(&issued.credential).unwrap_err();
    assert!(matches!(err, VerifyError::Expired), "{err:?}");
}

#[test]
fn a_credential_that_is_not_yet_valid_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let mut request = membership_request(&holder);
    request.not_before = Some(NOW + DAY);
    let issued = harbour().issue(&store, &request).unwrap();
    let err = verifier(store).verify_credential(&issued.credential).unwrap_err();
    assert!(matches!(err, VerifyError::NotYetValid), "{err:?}");
}

#[test]
fn a_revoked_credential_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    revoke_credential(&store, issued.credential["id"].as_str().unwrap()).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    let err = verifier(store).verify_presentation(&submission("req-1", vp), NONCE, DOMAIN).unwrap_err();
    assert!(matches!(err, VerifyError::Revoked), "{err:?}");
}

#[test]
fn a_proof_by_a_key_the_issuer_does_not_list_is_rejected() {
    let store = store();
    let holder = Holder::new(1);
    let mut issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let key = ed25519_dalek::SigningKey::from_bytes(&seed(HARBOUR_SEED));
    let unlisted = format!("{HARBOUR_DID}#key-9");
    credential::sign(&mut issued.credential, &key, &unlisted, "assertionMethod", NOW);
    let err = verifier(store).verify_credential(&issued.credential).unwrap_err();
    assert!(matches!(err, VerifyError::UnknownKey(ref id) if *id == unlisted), "{err:?}");
}

#[test]
fn a_credential_without_an_issuer_is_malformed() {
    let err = verifier(store()).verify_credential(&json!({ "credentialSubject": {} })).unwrap_err();
    assert!(matches!(err, VerifyError::Malformed(_)), "{err:?}");
}

